{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 자전거이용 활성화에 관한 조례상 같은 곳에 10일째 방치된 자전거를 구청이 바로 버릴 수 있는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "조례 제10조제2항에 따르면 구청장은 주차 후 동일 장소에 무단으로 10일 이상 방치된 자전거에 대하여 소유자나 위탁자에게 무단방치 여부를 확인하고, 무단방치로 판명된 때에 법 제20조 및 영 제11조에 따라 처분할 수 있다. 따라서 10일째라는 사실만으로 바로 버릴 수 있는 것이 아니라, 확인 절차와 무단방치 판명이라는 요건이 충족되어야 처분할 수 있다.",
          "b_ids": "자전거:제10조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
